from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    cells = defaultdict(set)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cells[grid[r][c]].add((r, c))

    rays = set()
    for color, pts in cells.items():
        other = [(r, c) for col, ps in cells.items() if col != color for r, c in ps]
        if not other:
            continue
        mr = sum(r for r, c in other) / len(other)
        mc = sum(c for r, c in other) / len(other)
        for r, c in pts:
            for dr in (-1, 1):
                for dc in (-1, 1):
                    q = (r + dr, c + dc)
                    if q not in pts or (r, c) > q:
                        continue
                    # Continue from the pair endpoint whose continuation moves
                    # farther away from the differently-colored seed motif.
                    ends = ((r, c, -dr, -dc), (q[0], q[1], dr, dc))
                    er, ec, sr, sc = max(
                        ends,
                        key=lambda e: (e[0] + e[2] - mr) ** 2 + (e[1] + e[3] - mc) ** 2,
                    )
                    rays.add((color, er + sr, ec + sc, sr, sc))
    for color, r, c, dr, dc in rays:
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] != bg:
                break
            out[r][c] = color
            r += dr
            c += dc
    return out

